package com.lianxibu.site.service.learning;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.service.identity.IdentityService.Actor;
import java.util.*;
import org.junit.jupiter.api.Test;
class OwnerPackageReadServiceTest {
 final Actor owner=new Actor("fictional-owner","owner");
 Map<String,Object> read(OwnerPackageReadService.Snapshot row){return new OwnerPackageReadService(id->row).read(owner,"fictional-package");}
 @Test void authorizationAndFullWireIdentityPrecedeStorage(){var store=mock(OwnerPackageReadService.Store.class);var service=new OwnerPackageReadService(store);for(Actor actor:new Actor[]{null,new Actor("fictional-user","user"),new Actor("","owner")})assertThrows(OwnerPackageReadService.Denied.class,()->service.read(actor,"bad\n"));for(String id:List.of("","bad\n","x".repeat(65),"\ud800"))assertThrows(IllegalArgumentException.class,()->service.read(owner,id));verifyNoInteractions(store);}
 @Test void allPhysicalStatesAndKnownZeroEmptyRemainExplicitAndImmutable(){for(String state:List.of("draft","approved","published","withdrawn")){var value=read(new OwnerPackageReadService.Snapshot("fictional-package","Fictional title","",0L,state));assertEquals(state,value.get("state"));assertEquals(0L,value.get("revision"));assertEquals("",value.get("description"));assertEquals(5,value.size());assertThrows(UnsupportedOperationException.class,()->value.put("validation_errors",List.of()));}}
 @Test void unknownFactsNeverBecomeEmptyZeroOrDraft(){var value=read(new OwnerPackageReadService.Snapshot("fictional-package",null,null,null,null));for(String field:List.of("title","description","revision","state"))assertTrue(value.containsKey(field)&&value.get(field)==null,field);}
 @Test void missingStorageAndWrongPackageAreSanitized(){assertThrows(OwnerPackageReadService.Missing.class,()->read(null));assertThrows(OwnerPackageReadService.Unavailable.class,()->read(new OwnerPackageReadService.Snapshot("fictional-other","Fictional",null,1L,"draft")));var service=new OwnerPackageReadService(id->{throw new IllegalStateException("Fictional raw storage diagnostic");});var failure=assertThrows(OwnerPackageReadService.Unavailable.class,()->service.read(owner,"fictional-package"));assertFalse(failure.getMessage().contains("diagnostic"));assertThrows(OwnerPackageReadService.Unavailable.class,()->read(new OwnerPackageReadService.Snapshot("fictional-package","Fictional",null,1L,"validating")));}
 @Test @SuppressWarnings("unchecked") void actualReviewedTwentySevenSchemaVectorsMatchProvider()throws Exception{var json=tools.jackson.databind.json.JsonMapper.shared();var cases=json.readTree(java.nio.file.Files.readAllBytes(java.nio.file.Path.of("../contracts/owner-package-wire-examples.json"))).get("cases");assertEquals(27,cases.size());for(var c:cases){Map<String,Object> value=json.convertValue(c.get("data"),Map.class);boolean accepted;try{OwnerPackageReadService.validateProjection(value,"fictional-package");accepted=true;}catch(OwnerPackageReadService.Unavailable invalid){accepted=false;}assertEquals(c.get("valid").booleanValue(),accepted,c.get("name").asText());}}
 @Test void fullCodePointBoundariesAndSafeIntegerAreReadable(){var value=read(new OwnerPackageReadService.Snapshot("fictional-package","🙂".repeat(200),"🙂".repeat(16384),9007199254740991L,"draft"));assertEquals(16384,((String)value.get("description")).codePointCount(0,32768));assertThrows(OwnerPackageReadService.Unavailable.class,()->read(new OwnerPackageReadService.Snapshot("fictional-package","🙂".repeat(201),"",1L,"draft")));}
}
